const b = $input.first().json.body || {};
const dealId = String(b.dealId || '').trim();
const generations = Array.isArray(b.generations) ? b.generations : [];
if (!dealId) return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'Missing dealId' } } }];
if (!generations.length) {
  return [{ json: { ok: false, statusCode: 400, body: { success: false, error: 'No generations supplied (nothing to place).' } } }];
}
return [{ json: { ok: true, dealId, clientOid: b.eclipseOrderId || '', generations } }];

// The deal's [E] Order ID is the source of truth (the client value is only
// a fallback). It must carry the gen suffix: that gen is the SOURCE the rep
// is placing from, and the only gen whose lines get drained.
const v = $('Validate').first().json;
const deal = $input.first().json;
if (deal.error) {
  return [{ json: { ok: false, statusCode: 500, body: { success: false, error: 'HubSpot deal fetch failed: ' + deal.error, step: 'preflight' } } }];
}
const rawOid = (deal.properties || {}).e_sorder_id || v.clientOid;
if (!rawOid) {
  return [{ json: { ok: false, statusCode: 400, body: { success: false, step: 'preflight',
    error: 'Deal has no Eclipse Order ID ([E] Order ID / e_sorder_id) set. Add it to the deal before placing.' } } }];
}
const rawOidStr = String(rawOid);
const dotIdx = rawOidStr.indexOf('.');
const oid = dotIdx >= 0 ? rawOidStr.slice(0, dotIdx) : rawOidStr;
const rawSourceGen = dotIdx >= 0 ? rawOidStr.slice(dotIdx + 1) : null;
if (!rawSourceGen) {
  return [{ json: { ok: false, statusCode: 400, body: { success: false, step: 'preflight',
    error: 'Eclipse Order ID for deal ' + v.dealId + ' ("' + rawOidStr + '") is missing the generation suffix (expected form "Sxxxxxxx.NNNN"). Set the deal\'s [E] Order ID to include the gen the rep is placing from.' } } }];
}
return [{ json: { ok: true, rawOidStr, oid, rawSourceGen, sourceGenId: String(Number(rawSourceGen)) } }];

// STEP 2 of the app function: reuse an existing gen whose
// (branch, requiredDate, shipDate, status) matches, otherwise create one.
// Emits one item per gen to create (consumed by Create Shipment), or a
// single { create: false } item. Planning state rides on the first item.
const pre = $('Preflight OID').first().json;
const { oid, rawOidStr, rawSourceGen, sourceGenId } = pre;
const generations = $('Validate').first().json.generations;
const env = $input.first().json;
if (env.error) {
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'getSalesOrder',
    error: 'Eclipse GET /SalesOrders/' + oid + ' failed: ' + env.error + (env.message ? ' ' + JSON.stringify(env.message).substring(0, 500) : '') } } }];
}
const so = (Array.isArray(env.results) ? env.results[0] : env) || {};
if (!so || (!so.generations && !so.lines)) {
  return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'getSalesOrder',
    error: 'Eclipse order ' + oid + ' not found.' } } }];
}

const d = new Date();
const todayIso = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const existingGens = Array.isArray(so.generations) ? so.generations : [];
const genKey = (branch, reqDate, shipDate, status) => [branch, reqDate, shipDate, status].map(String).join('|');
const existingByKey = {};
const cancelledGens = [];
for (const g of existingGens) {
  if (String(g.status) === 'Cancel') { cancelledGens.push(String(g.generationId)); continue; }
  const key = genKey(g.shipBranch, g.requiredDate, g.shipDate, g.status);
  if (!(key in existingByKey)) existingByKey[key] = g.generationId;
}
const existingGenIds = existingGens.map((g) => String(g.generationId));
if (!existingGenIds.includes(sourceGenId)) {
  return [{ json: { ok: false, statusCode: 400, body: { success: false, step: 'preflight',
    error: 'Eclipse Order ID "' + rawOidStr + '" points at gen ' + rawSourceGen + ', which doesn\'t exist on order ' + oid + '. Update the deal\'s [E] Order ID to a valid gen.' } } }];
}
if (cancelledGens.includes(sourceGenId)) {
  return [{ json: { ok: false, statusCode: 400, body: { success: false, step: 'preflight',
    error: 'Eclipse Order ID "' + rawOidStr + '" points at gen ' + rawSourceGen + ', which is cancelled. Update the deal\'s [E] Order ID to an active gen before placing.' } } }];
}

// linesByGenProduct[gid][pid] = [{ lineId, qty }], umByProduct[pid] = { um, umQuantity }
const linesByGenProduct = {};
const umByProduct = {};
for (const line of (Array.isArray(so.lines) ? so.lines : [])) {
  if (line.lineId == null || line.productId == null) continue;
  const pid = String(line.productId);
  if (!umByProduct[pid]) {
    umByProduct[pid] = { um: line.displayUom || line.smallestUom || 'ea', umQuantity: Number(line.displayUomQty) || 1 };
  }
  for (const lg of (Array.isArray(line.generations) ? line.generations : [])) {
    if (lg.generationId == null) continue;
    const gid = String(lg.generationId);
    if (cancelledGens.includes(gid)) continue;
    const qty = (Number(lg.stockQty) || 0) + (Number(lg.nonstockQty) || 0);
    linesByGenProduct[gid] = linesByGenProduct[gid] || {};
    linesByGenProduct[gid][pid] = linesByGenProduct[gid][pid] || [];
    linesByGenProduct[gid][pid].push({ lineId: line.lineId, qty });
  }
}

// desired[] keeps the client's order; reused gens are filled in now,
// created gens get their id from Create Shipment.
const desired = [];
const toCreate = [];
for (let i = 0; i < generations.length; i++) {
  const gen = generations[i];
  const requiredDate = gen.requiredDate || todayIso;
  const shipDate = gen.shipDate || todayIso;
  const shipStatus = gen.shipStatus || 'ShipWhenAvailable';
  const shipBranch = String(gen.branchId);
  const key = genKey(shipBranch, requiredDate, shipDate, shipStatus);
  const entry = { branchId: shipBranch, lineItems: gen.lineItems || [], requiredDate, shipDate, shipStatus };
  if (key in existingByKey) {
    entry.generationId = existingByKey[key];
    entry.reused = true;
    delete existingByKey[key];
  } else {
    entry.reused = false;
    entry.createIndex = toCreate.length;
    toCreate.push({ shipBranch, requiredDate, shipDate, shipStatus });
  }
  desired.push(entry);
}

const state = { oid, sourceGenId, desired, linesByGenProduct, umByProduct, getSalesOrder: so };
if (!toCreate.length) return [{ json: { ok: true, create: false, state } }];
return toCreate.map((c, idx) => ({ json: {
  ok: true, create: true, oid, ...c, state: idx === 0 ? state : undefined,
} }));

// STEP 3 planning of the app function.
//   Pass A: per destination (gen, product), POST the deficit or drain the
//           surplus (DELETE lines that would hit 0, PUT the rest).
//   Pass B: DELETE every source-gen line for a placed product the rep is
//           not keeping on the source gen.
// Calls are addressed with the gen-scoped id (S1234567.0006), which is
// what the Eclipse node's line-item operations expect.
const planItems = $('Plan generations').all();
const state = planItems[0].json.state;
const { oid, sourceGenId, linesByGenProduct, umByProduct } = state;
const desired = state.desired;
const padGenId = (g) => String(g).padStart(4, '0');
const shipments = $('Eclipse: create shipment').isExecuted ? $('Eclipse: create shipment').all() : [];
const eclipseResponses = { getSalesOrder: state.getSalesOrder, shipments: [], lineItems: [] };

const createdGenerations = [];
for (const entry of desired) {
  let generationId = entry.generationId;
  if (!entry.reused) {
    const res = shipments[entry.createIndex] ? shipments[entry.createIndex].json : null;
    eclipseResponses.shipments.push({ reused: false, desired: { shipBranch: entry.branchId, requiredDate: entry.requiredDate, shipDate: entry.shipDate, shipStatus: entry.shipStatus }, body: res });
    if (!res || res.error) {
      return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createShipment', createdGenerations, eclipseResponses,
        error: 'Eclipse POST /Shipment failed for branch ' + entry.branchId + ': ' + (res ? res.error + ' ' + JSON.stringify(res.message || '').substring(0, 500) : 'no response') } } }];
    }
    generationId = res.generationId || res.generationID;
    if (!generationId) {
      return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'createShipment', createdGenerations, eclipseResponses,
        error: 'Eclipse POST /Shipment succeeded for branch ' + entry.branchId + ' but response had no generationId: ' + JSON.stringify(res).substring(0, 500) } } }];
    }
  } else {
    eclipseResponses.shipments.push({ reused: true, matchedGenerationId: generationId, desired: { shipBranch: entry.branchId, requiredDate: entry.requiredDate, shipDate: entry.shipDate, shipStatus: entry.shipStatus } });
  }
  createdGenerations.push({
    generationId: String(Number(generationId)), branchId: entry.branchId, lineItems: entry.lineItems,
    reused: entry.reused, requiredDate: entry.requiredDate, shipDate: entry.shipDate, shipStatus: entry.shipStatus,
  });
}

const currentQtyOnGen = (gid, pid) => ((linesByGenProduct[gid] || {})[pid] || []).reduce((s, l) => s + l.qty, 0);

const desiredByGenProduct = {};
for (const gen of createdGenerations) {
  const gid = gen.generationId;
  desiredByGenProduct[gid] = desiredByGenProduct[gid] || {};
  for (const li of gen.lineItems || []) {
    if (!li.eclipseProductId) continue;
    const pid = String(li.eclipseProductId);
    desiredByGenProduct[gid][pid] = (desiredByGenProduct[gid][pid] || 0) + (Number(li.quantity) || 0);
  }
}
const placedProductIds = new Set();
for (const byProduct of Object.values(desiredByGenProduct)) for (const pid of Object.keys(byProduct)) placedProductIds.add(pid);

const plannedPosts = [];
const plannedDeletes = [];
const plannedPuts = [];
for (const [gid, byProduct] of Object.entries(desiredByGenProduct)) {
  for (const [pid, desiredQty] of Object.entries(byProduct)) {
    const currentQty = currentQtyOnGen(gid, pid);
    if (desiredQty > currentQty) {
      const um = umByProduct[pid];
      if (!um) {
        return [{ json: { ok: false, statusCode: 500, body: { success: false, step: 'planLineItems', createdGenerations, eclipseResponses,
          error: 'No Eclipse line found for product ' + pid + ' on order ' + oid + '. Add a line for it to the order before placing.' } } }];
      }
      plannedPosts.push({ genId: gid, productId: pid, qty: desiredQty - currentQty, um: um.um, umQuantity: um.umQuantity });
    } else if (desiredQty < currentQty) {
      let toDrain = currentQty - desiredQty;
      for (const line of ((linesByGenProduct[gid] || {})[pid] || [])) {
        if (toDrain <= 0) break;
        if (line.qty <= 0) continue;
        const drainAmount = Math.min(line.qty, toDrain);
        const newQty = line.qty - drainAmount;
        if (newQty === 0) plannedDeletes.push({ genId: gid, lineId: line.lineId });
        else plannedPuts.push({ genId: gid, lineId: line.lineId, qty: newQty, productId: pid });
        toDrain -= drainAmount;
      }
    }
  }
}
const sourceLines = linesByGenProduct[sourceGenId] || {};
const sourceDesired = desiredByGenProduct[sourceGenId] || {};
for (const [pid, lineList] of Object.entries(sourceLines)) {
  if (!placedProductIds.has(pid)) continue;
  if (sourceDesired[pid] != null) continue;
  for (const line of lineList) if (line.qty > 0) plannedDeletes.push({ genId: sourceGenId, lineId: line.lineId });
}

// Group per gen. DELETE supersedes PUT on the same line.
const postGroups = {};
for (const p of plannedPosts) {
  postGroups[p.genId] = postGroups[p.genId] || { genId: p.genId, orderId: oid + '.' + padGenId(p.genId), items: [] };
  postGroups[p.genId].items.push({ lineItemProduct: { productId: Number(p.productId), quantity: p.qty, um: p.um, umQuantity: p.umQuantity } });
}
const deleteGroups = {};
for (const dl of plannedDeletes) {
  deleteGroups[dl.genId] = deleteGroups[dl.genId] || { genId: dl.genId, orderId: oid + '.' + padGenId(dl.genId), lineIds: [] };
  if (!deleteGroups[dl.genId].lineIds.includes(dl.lineId)) deleteGroups[dl.genId].lineIds.push(dl.lineId);
}
const putGroups = {};
for (const p of plannedPuts) {
  if (deleteGroups[p.genId] && deleteGroups[p.genId].lineIds.includes(p.lineId)) continue;
  putGroups[p.genId] = putGroups[p.genId] || { genId: p.genId, orderId: oid + '.' + padGenId(p.genId), byLine: {} };
  const prev = putGroups[p.genId].byLine[p.lineId];
  const um = (umByProduct[p.productId] || {}).um || 'ea';
  putGroups[p.genId].byLine[p.lineId] = { lineId: Number(p.lineId), qty: prev ? Math.min(prev.qty, p.qty) : p.qty, um };
}
const plan = {
  postGroups: Object.values(postGroups),
  deleteGroups: Object.values(deleteGroups).map((g) => ({ ...g, lineIds: g.lineIds.join(',') })),
  putGroups: Object.values(putGroups).map((g) => ({ genId: g.genId, orderId: g.orderId, items: Object.values(g.byLine) })),
};
return [{ json: {
  ok: true, oid, sourceGenId, createdGenerations, eclipseResponses, plan,
  hasPosts: plan.postGroups.length > 0,
  hasDeletes: plan.deleteGroups.length > 0,
  hasPuts: plan.putGroups.length > 0,
} }];

const plan = $('Plan line ops').first().json;
const groups = plan.plan.postGroups;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'postLineItems',
      createdGenerations: plan.createdGenerations, eclipseResponses: plan.eclipseResponses,
      error: 'Eclipse POST /LineItems failed (gen ' + (groups[i] || {}).genId + '): ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500) } } }];
  }
}
return [{ json: { ok: true } }];

const plan = $('Plan line ops').first().json;
const groups = plan.plan.deleteGroups;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'deleteLineItems',
      createdGenerations: plan.createdGenerations, eclipseResponses: plan.eclipseResponses,
      error: 'Eclipse DELETE /LineItems failed (gen ' + (groups[i] || {}).genId + '): ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500) } } }];
  }
}
return [{ json: { ok: true } }];

const plan = $('Plan line ops').first().json;
const groups = plan.plan.putGroups;
const out = $input.all();
for (let i = 0; i < out.length; i++) {
  const r = out[i].json;
  if (r.error) {
    return [{ json: { ok: false, statusCode: 502, body: { success: false, step: 'putQtyLineItems',
      createdGenerations: plan.createdGenerations, eclipseResponses: plan.eclipseResponses,
      error: 'Eclipse PUT /QtyLineItems failed (gen ' + (groups[i] || {}).genId + '): ' + r.error + ' ' + JSON.stringify(r.message || '').substring(0, 500) } } }];
  }
}
return [{ json: { ok: true } }];

// STEP 4: cancel every non-cancelled gen that ended up with no lines or
// total qty 0 (usually the drained source gen). Best-effort.
const plan = $('Plan line ops').first().json;
const env = $input.first().json;
if (env.error) {
  return [{ json: { cancel: false, cleanupError: { phase: 'post-GET', message: String(env.error) } } }];
}
const so = (Array.isArray(env.results) ? env.results[0] : env) || {};
const qtyByGen = {};
const hasLines = new Set();
for (const line of (so.lines || [])) {
  for (const lg of (line.generations || [])) {
    if (lg.generationId == null) continue;
    const k = String(lg.generationId);
    hasLines.add(k);
    qtyByGen[k] = (qtyByGen[k] || 0) + (Number(lg.stockQty) || 0) + (Number(lg.nonstockQty) || 0);
  }
}
const toCancel = [];
for (const g of (so.generations || [])) {
  if (String(g.status) === 'Cancel') continue;
  const k = String(g.generationId);
  if (!hasLines.has(k) || (qtyByGen[k] || 0) === 0) toCancel.push(k);
}
if (!toCancel.length) return [{ json: { cancel: false } }];
return toCancel.map((gid) => ({ json: { cancel: true, generationId: gid, statusOrderId: plan.oid + '.' + gid.padStart(4, '0') } }));

// STEP 5: every gen this placement touched (created, reused, source,
// cancelled) is sent to update-hs-deal in one call. Replaces the dead
// Celigo export.
const plan = $('Plan line ops').first().json;
const padGenId = (g) => String(g).padStart(4, '0');
const cleanup = { cancelled: [], errors: [] };
const planned = $('Plan cleanup').all();
if (planned[0] && planned[0].json.cleanupError) cleanup.errors.push(planned[0].json.cleanupError);
if ($('Eclipse: cancel empty gen').isExecuted) {
  const res = $('Eclipse: cancel empty gen').all();
  res.forEach((r, i) => {
    const gid = planned[i] && planned[i].json.generationId;
    if (r.json.error) cleanup.errors.push({ phase: 'cancel', generationId: gid, message: r.json.error, body: r.json.message });
    else cleanup.cancelled.push({ generationId: gid });
  });
}
const reasons = new Map();
const add = (gid, reason) => {
  const k = String(Number(gid));
  reasons.set(k, reasons.has(k) ? reasons.get(k) + ' + ' + reason : reason);
};
for (const g of plan.createdGenerations) add(g.generationId, g.reused ? 'reused' : 'created');
add(plan.sourceGenId, 'source');
for (const c of cleanup.cancelled) add(c.generationId, 'cancelled');
const syncTargets = [...reasons.entries()].map(([gid, reason]) => ({ generationId: gid, reason, eSorderId: plan.oid + '.' + padGenId(gid) }));
return [{ json: { cleanup, syncTargets, e_sorder_ids: syncTargets.map((t) => t.eSorderId) } }];

const plan = $('Plan line ops').first().json;
const sync = $('Sync list').first().json;
const r = $input.first().json || {};
const eclipseResponses = { ...plan.eclipseResponses, lineItems: [] };
const collect = (node, op) => {
  if (!$(node).isExecuted) return;
  for (const it of $(node).all()) eclipseResponses.lineItems.push({ op, body: it.json });
};
collect('Eclipse: POST /LineItems', 'POST /LineItems');
collect('Eclipse: DELETE /LineItems', 'DELETE /LineItems');
collect('Eclipse: PUT /QtyLineItems', 'PUT /QtyLineItems');
eclipseResponses.cleanup = sync.cleanup;
eclipseResponses.hubspotSync = r.error
  ? { triggered: [], errors: [{ message: String(r.error), targets: sync.syncTargets }] }
  : { triggered: sync.syncTargets, errors: [], response: r };
return [{ json: { statusCode: 200, body: {
  success: true,
  eclipseOrderId: plan.oid,
  createdGenerations: plan.createdGenerations,
  eclipseResponses,
} } }];
